"""Build v10: one continuous 2D frequency-world, with seek-safe GSAP motion."""
from pathlib import Path
import subprocess

ROOT = Path(__file__).parent
SHOTS = [
    ('01',0,8),('02',8,16),('03',24,10),('04',34,11),('05',45,12),
    ('06',57,10),('07',67,10),('08',77,12),('09',89,12),('10',101,9),('11',110,9),
]

def rail(sid, aperture=1, compact=False):
    cells=''.join(f'<div class="cell"><i></i><b>{i:02}</b></div>' for i in range(1,17))
    return f'<div class="rail {"compact" if compact else ""}" id="rail-{sid}"><div class="rail-label">FREQUENCY / 16 BANDS</div><div class="cellrow">{cells}<div class="aperture" id="ap-{sid}" style="left:{(aperture-1)*6.25}%"></div></div><div class="rail-caption"><span>LOW FREQUENCY</span><span>HIGH FREQUENCY</span></div></div>'

def head(kicker,title,subtitle=''):
    return f'<div class="head"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p>{subtitle}</p></div>'

def pulse(sid,number,pos,color='miss'):
    return f'<div id="pulse-{sid}-{number}" class="burst {color}" style="left:{pos}%"></div>'

def foot(label):
    return f'<div class="footline"><span>SMART SCAN / SOLUTION</span><span>{label}</span></div>'

SC={}
SC['01']=head('01 / THE MISSED BURST','The signal was there.','The receiver arrived after it vanished.')+f'''<div class="hero-miss" id="miss-word">MISSED</div><div class="beam" id="beam-01"></div>{rail('01',4)}{pulse('01',1,79)}<div class="takeaway">A short transmission needs the right frequency <em>at the right time.</em></div>'''+foot('THE PROBLEM CONTINUES')

SC['02']=head('02 / PHYSICAL RECEIVER','The window is set by hardware.','Wide radio environment → narrow instantaneous view.')+f'''<div class="hardware-stage"><div class="antenna-illustration" id="antenna-02"><svg viewBox="0 0 300 360"><defs><linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d8ebf4"/><stop offset=".5" stop-color="#49718b"/><stop offset="1" stop-color="#eaf4f5"/></linearGradient></defs><path d="M150 293V88 M87 290h126 M116 301h68 M151 90L58 34 M151 90l95-56 M87 72q63 94 126 0" fill="none" stroke="url(#metal)" stroke-width="12" stroke-linecap="round"/><circle cx="151" cy="90" r="15" fill="#55ddeb"/><path class="radio-wave" d="M55 90q95-90 190 0 M31 105q120-126 238 0" fill="none" stroke="#56dce9" stroke-width="5"/></svg><strong>ANTENNA</strong></div><div class="flowtrack"><div class="packet" id="packet-02-a"></div><div class="packet" id="packet-02-b"></div><div class="packet" id="packet-02-c"></div></div><div class="tuner-illustration"><div class="tuner-top">RF FRONT END <span>→</span> TUNER <span>→</span> ADC</div><div class="tuner-innards"><div class="wide-input">16<br><small>bands in</small></div><div class="gate" id="gate-02"><i></i><i></i></div><div class="narrow-output">2<br><small>bands sampled</small></div></div><div class="tuner-bottom">COMPUTE SCORES WHAT THE SCAN HEARD</div></div></div><div class="hardware-note"><span class="big-ratio">≥10×</span><div><b>Problem statement: typical receiver window is at least ten times narrower than the monitored span.</b><small>Project simulator: 2 adjacent bands out of 16 (8× illustrative ratio).</small></div></div>{rail('02',6,True)}'''+foot('HARDWARE CONSTRAINT')

SC['03']=head('03 / CONSEQUENCE','The narrow window must move.','A burst outside it is not visible at that instant.')+f'''<div class="scan-stage"><div class="scan-caption">ONE RECEIVER / TWO BANDS AT A TIME</div>{rail('03',2)}{pulse('03',1,70)}{pulse('03',2,39)}{pulse('03',3,84)}<div class="scan-verdict"><span class="miss-label" id="miss-03">MISSED BURST</span><span class="choice-label">SOFTWARE CHOOSES THE NEXT TUNING POSITION</span></div></div>'''+foot('FIXED PHYSICAL LIMIT')

nodes=''.join(f'<div class="loop-node" id="node-04-{i}"><span>0{i}</span><b>{name}</b><small>{desc}</small></div>' for i,(name,desc) in enumerate([('OBSERVE','hear the current pair'),('UPDATE','record the evidence'),('CHOOSE','select the next pair'),('RETUNE','move the window')],1))
SC['04']=head('04 / THE SCAN LOOP','Every scan changes the next decision.','All six strategies get the same virtual receiver and time budget.')+f'''<div class="loop-stage">{nodes}<div class="loop-connector"></div><div class="loop-token" id="loop-token"></div></div><div class="belief-strip"><span>BAND HISTORY</span>{''.join(f'<i id="belief-{i}" style="height:{26+i*11%75}%"></i>' for i in range(1,17))}</div>{rail('04',5,True)}'''+foot('OBSERVE → UPDATE → CHOOSE → RETUNE')

def minirail(label,sid):
    return f'<div class="model-rail"><div class="model-title">{label}</div><div class="model-cells">'+''.join('<i></i>' for _ in range(16))+f'<div class="model-window" id="mw-{sid}"></div></div></div>'
SC['05']=head('05 / DESIGNED SCHEDULERS','Two rule-based ways to choose.','These are calculated strategies, not neural networks.')+f'''<div class="comparison"><div class="strategy"><div class="strategy-name">CTMC</div><div class="strategy-desc">Keeps a chance of visiting every band.</div>{minirail('RANDOMIZED COVERAGE','ctmc')}<div class="decision-note"><span class="die" id="die-05">◆</span> A little unpredictability breaks a rigid rhythm.</div></div><div class="strategy"><div class="strategy-name">INDEX</div><div class="strategy-desc">Ranks likely activity and overdue revisits.</div>{minirail('BELIEF + REVISIT AGE','index')}<div class="rankrow">{''.join(f'<div><span>BAND {n:02}</span><i style="width:{w}%"></i></div>' for n,w in [(3,80),(11,65),(7,48)])}</div></div></div>{rail('05',3,True)}'''+foot('SAME RECEIVER / TWO DESIGNED RULES')

SC['06']=head('06 / LEARNING FROM REWARD','Two ways to remember what worked.','Feedback shifts future choices; the receiver remains the same.')+f'''<div class="learn-pair"><div class="learn-panel"><h2>BANDIT</h2><p>Try a new band, or use one that paid off.</p><div class="armbars">{''.join(f'<div class="arm"><i id="arm-{i}" style="height:{h}%"></i><b>{i:02}</b></div>' for i,h in [(1,38),(2,74),(3,55),(4,45)])}</div><div class="reward">REWARD → UPDATE ESTIMATE</div></div><div class="learn-panel"><h2>Q-LEARNING</h2><p>Keep a score for each choice in each situation.</p><div class="qtable">{''.join(f'<i id="q-{i}"></i>' for i in range(24))}</div><div class="reward">STATE + ACTION → VALUE TABLE</div></div></div>{rail('06',4,True)}'''+foot('LEARNED POLICIES / REWARD FEEDBACK')

net='<svg id="net-07" viewBox="0 0 620 310">'+''.join(f'<path d="M{85+li*220} {55+yi*65} L{305+li*220} {35+yj*48}" />' for li in range(2) for yi in range(4) for yj in range(5))+''.join(f'<circle cx="{x}" cy="{y}" r="14" />' for x,ys in [(85,[55,120,185,250]),(305,[35,83,131,179,227]),(525,[35,83,131,179,227])] for y in ys)+'</svg>'
SC['07']=head('07 / NEURAL LEARNING','Two deeper policy families.','Different internal representations; the same two-band action.')+f'''<div class="learn-pair neural"><div class="learn-panel"><h2>DQN</h2><p>A network estimates the value of each next scan.</p>{net}<div class="reward">STATE → ACTION VALUES</div></div><div class="learn-panel"><h2>PPO</h2><p>Training adjusts probabilities of scan choices.</p><div class="probchart">{''.join(f'<div><span>{i:02}</span><i id="prob-{i}" style="height:{h}%"></i></div>' for i,h in [(1,48),(2,65),(3,38),(4,72),(5,42)])}</div><div class="reward">STATE → PROBABILITY POLICY</div></div></div>{rail('07',7,True)}'''+foot('LEARNED POLICIES / DEEPER METHODS')

SC['08']=head('08 / TEST INPUTS','Two data sources. One virtual receiver.','The replay is synthetic radar data, not a live RF feed.')+f'''<div class="data-stage"><div class="data-source"><h2>GENERATED SCENARIOS</h2><p>Periodic, agile and intermittent emitter patterns.</p><div class="timeline-wave" id="wave-08">{''.join(f'<i style="height:{v}%"></i>' for v in [12,16,90,13,18,75,17,13,92,12,65,17,12,80,15,12,45,90,13,16,72,13,90,15])}</div></div><div class="flow-arrow" id="arrow-08">→</div><div class="data-source"><h2>ALAN TURING REPLAY</h2><p>Synthetic radar pulses grouped by time and frequency.</p><div class="dotfield">{''.join(f'<i style="left:{(i*37)%92+3}%;top:{(i*53)%75+12}%"></i>' for i in range(32))}</div></div></div><div class="virtual-gate" id="gate-08">VIRTUAL RECEIVER <small>same two-band window</small></div>{rail('08',8,True)}'''+foot('SIMULATION ONLY / NO FIELD RECEIVER')

SC['09']=head('09 / HELD-OUT SCENARIO B','The same window, more signals seen.','Six held-out runs, 2,000 steps each. Detection of active band-time.')+f'''<div class="graph-stage"><div class="graph-row"><b>FIXED SWEEP</b><div class="graph-track"><i id="bar-base" style="width:72.8%"></i></div><strong>0.1092</strong></div><div class="graph-row"><b>INDEX</b><div class="graph-track"><i id="bar-index" style="width:88.93%"></i></div><strong>0.1334</strong></div><div class="graph-axis"><span>0</span><span>GRAPH ZOOMED TO 0.15 DETECTION PROBABILITY</span><span>0.15</span></div><div class="lift"><strong id="lift-09">+22%</strong><span>relative improvement over the fixed sweep</span></div></div>{rail('09',10,True)}'''+foot('SOURCE: SCHEDULER IMPLEMENTATION / SCENARIO B')

def reach(label,value,color,extra=''):
    return f'<div class="reach-row {color}"><b>{label}</b><div class="reach-track"><i style="width:{value}%"></i></div><strong>{value:.2f}%</strong>{extra}</div>'
SC['10']=head('10 / A SECOND MEASURE','How many different emitters were reached?','Detection and emitter coverage tell different parts of the story.')+f'''<div class="coverage-stage">{reach('FIXED SWEEP',96.67,'base')}{reach('INDEX',96.67,'index')}{reach('BANDIT*',71.0,'bandit','<span>more detection, less reach</span>')}<div class="separate">*Bandit figure comes from a separate 20-run evaluation; it is not the matched six-run comparison.</div></div>{rail('10',12,True)}'''+foot('TRADEOFFS MATTER')

SC['11']=head('11 / THE TAKEAWAY','A better decision on every scan.','The receiver stays narrow. The scheduling choice changes.')+f'''<div class="final-stage"><div class="final-fact"><span>TRAINING WALL TIME</span><b>NOT RECORDED COMPARABLY</b></div><div class="final-fact"><span>WARM SCHEDULER API</span><b>6.6 ms p95 DECISION LATENCY</b></div><div class="final-mark">PUSHPAK <small>SMART SCAN / SIMULATION</small></div></div>{rail('11',8,True)}'''+foot('SOLUTION CHAPTER COMPLETE')

