clips='\n'.join(f'<section class="clip" data-start="{start}" data-duration="{dur}" id="clip-{sid}"><div class="scene" id="s{sid}">{SC[sid]}</div></section>' for sid,start,dur in SHOTS)
voices=[]
for sid,start,dur in SHOTS:
    path=ROOT/'assets'/'voice'/f'{sid}.wav'
    if path.exists():
        p=subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',str(path)],capture_output=True,text=True)
        vdur=float(p.stdout.strip())
        offset=.1 if sid=='11' else .25
        voices.append(f'<audio id="voice-{sid}" src="assets/voice/{sid}.wav" data-start="{start+offset}" data-duration="{vdur:.3f}" data-track-index="10" data-audio-group="voiceover"></audio>')
score='<audio id="score" src="assets/audio/score.wav" data-start="0" data-duration="119" data-track-index="2" data-volume=".56"></audio>'
sfx='<audio id="sfx" src="assets/audio/sfx.wav" data-start="0" data-duration="119" data-track-index="3" data-volume=".75"></audio>'

JS=r'''
window.__timelines=window.__timelines||{};
const tl=gsap.timeline({paused:true});
const shots=[['01',0,8],['02',8,16],['03',24,10],['04',34,11],['05',45,12],['06',57,10],['07',67,10],['08',77,12],['09',89,12],['10',101,9],['11',110,9]];
for(const [id,t,d] of shots){
  const s='#s'+id;
  tl.fromTo(s,{opacity:0},{opacity:1,duration:.4,ease:'sine.out'},t);
  tl.fromTo(s,{scale:1.018,y:10},{scale:1,y:-7,duration:d-.2,ease:'none'},t);
  tl.fromTo(s+' .head',{y:38,opacity:0},{y:0,opacity:1,duration:.85,ease:'power3.out'},t+.12);
  tl.fromTo(s+' .rail',{y:28,opacity:0},{y:0,opacity:1,duration:.8,ease:'power2.out'},t+.2);
  tl.to(s,{opacity:0,duration:.38,ease:'sine.in'},t+d-.4);
}
// The same two-band aperture remains the spatial anchor across each shot.
tl.fromTo('#ap-01',{x:0},{x:1030,duration:5.3,ease:'none'},1.1);
tl.fromTo('#pulse-01-1',{opacity:0,scaleY:.15},{opacity:1,scaleY:1,duration:.11},2.3);tl.to('#pulse-01-1',{opacity:0,duration:.18},2.63);
tl.fromTo('#miss-word',{opacity:0,scale:.85},{opacity:1,scale:1,duration:.34,ease:'power3.out'},3.1);
tl.to('#miss-word',{opacity:.4,duration:2.2},4.2);
tl.fromTo('#beam-01',{x:0},{x:1130,duration:5.2,ease:'none'},1.0);
// Hardware: energy enters; tuner gates the wide input down to two bands.
tl.fromTo('#antenna-02 .radio-wave',{opacity:.2,scale:.85},{opacity:1,scale:1.07,duration:1.25,repeat:7,yoyo:true,ease:'sine.inOut'},9);
tl.fromTo('#s02 .hardware-stage',{x:-90,opacity:.35},{x:0,opacity:1,duration:1.2,ease:'power3.out'},8.55);
for(const [i,at] of [['a',10.1],['b',13.2],['c',16.3]]){tl.fromTo('#packet-02-'+i,{x:0,opacity:0},{x:170,opacity:1,duration:.7,ease:'power2.in'},at);tl.to('#packet-02-'+i,{opacity:0,duration:.1},at+.7)}
tl.fromTo('#gate-02',{scaleX:1.5,opacity:.45},{scaleX:1,opacity:1,duration:1.8,ease:'power3.out'},11.2);
tl.fromTo('#s02 .hardware-note',{opacity:0,y:25},{opacity:1,y:0,duration:.7},17.0);
tl.fromTo('#ap-02',{x:0},{x:520,duration:11,ease:'sine.inOut'},10.4);
// Repeated visibly missed bursts; no claim of measured performance in illustrative shots.
tl.fromTo('#ap-03',{x:0},{x:1280,duration:8.4,ease:'none'},24.8);
for(const [n,at] of [[1,26.2],[2,28.6],[3,31.0]]){tl.fromTo('#pulse-03-'+n,{opacity:0,scaleY:.15},{opacity:1,scaleY:1,duration:.1},at);tl.to('#pulse-03-'+n,{opacity:0,duration:.19},at+.24)}
tl.fromTo('#miss-03',{opacity:0,scale:.8},{opacity:1,scale:1,duration:.35},27.0);
tl.fromTo('#s03 .scan-stage',{scale:1.035,opacity:.5},{scale:1,opacity:1,duration:1.1,ease:'power2.out'},24.3);
// A decision token cycles over the four operations, and belief bars change.
tl.fromTo('#loop-token',{x:0},{x:1400,duration:8.4,ease:'none'},35.2);
for(let i=1;i<=4;i++){tl.fromTo('#node-04-'+i,{borderColor:'#527a91',backgroundColor:'#17354a'},{borderColor:'#f2c16e',backgroundColor:'#2e3f48',duration:.5,yoyo:true,repeat:1},35.3+(i-1)*2.2)}
tl.fromTo('#s04 .belief-strip i',{scaleY:.35},{scaleY:1,duration:1.1,stagger:.08,ease:'power2.out'},37.5);
tl.fromTo('#s04 .loop-node',{y:50,opacity:0},{y:0,opacity:1,duration:.65,stagger:.16,ease:'power3.out'},34.5);
tl.fromTo('#ap-04',{x:0},{x:705,duration:8.2,ease:'steps(5)'},35.2);
// Rule-based schedulers: irregular path versus ranked destination.
for(const [x,t] of [[220,46.3],[440,48.2],[100,50.4],[630,52.2]]) tl.to('#mw-ctmc',{x,duration:.8,ease:'power2.inOut'},t);
tl.fromTo('#s05 .strategy:first-child',{x:-90,opacity:0},{x:0,opacity:1,duration:.85,ease:'power3.out'},45.3);
tl.fromTo('#s05 .strategy:last-child',{x:90,opacity:0},{x:0,opacity:1,duration:.85,ease:'power3.out'},45.6);
tl.fromTo('#die-05',{rotation:-40,scale:.7},{rotation:560,scale:1,duration:5.2,ease:'none'},46.3);
tl.fromTo('#s05 .rankrow i',{scaleX:.08},{scaleX:1,duration:1.3,stagger:.5,ease:'power2.out'},47.1);
tl.fromTo('#mw-index',{x:0},{x:560,duration:2.0,ease:'power3.inOut'},50.0);
tl.fromTo('#ap-05',{x:0},{x:930,duration:9,ease:'none'},46.0);
// Learning mechanisms update their own visible state.
tl.fromTo('#s06 .arm i',{scaleY:.3},{scaleY:1,duration:1.2,stagger:.28,ease:'back.out(1.4)'},58.4);
tl.fromTo('#s06 .learn-panel',{y:55,opacity:0},{y:0,opacity:1,duration:.75,stagger:.25,ease:'power3.out'},57.4);
tl.to('#arm-1',{scaleY:.76,duration:.6,yoyo:true,repeat:3},61.0);tl.to('#arm-3',{scaleY:1.22,duration:.5,yoyo:true,repeat:3},61.2);
for(const [n,t] of [[2,59.5],[9,60.3],[15,61.1],[21,61.9]]) tl.fromTo('#q-'+n,{backgroundColor:'#275570',scale:1},{backgroundColor:'#f0bf69',scale:1.16,duration:.34,yoyo:true,repeat:1},t);
tl.fromTo('#ap-06',{x:0},{x:920,duration:8,ease:'none'},58);
tl.fromTo('#net-07 path',{opacity:.08},{opacity:.75,duration:.7,stagger:.013,yoyo:true,repeat:1},68.5);
tl.fromTo('#s07 .learn-panel',{y:55,opacity:0},{y:0,opacity:1,duration:.75,stagger:.25,ease:'power3.out'},67.4);
tl.fromTo('#net-07 circle',{scale:.8,opacity:.3},{scale:1,opacity:1,duration:.45,stagger:.04,yoyo:true,repeat:2},69.2);
tl.fromTo('#s07 .probchart i',{scaleY:.3},{scaleY:1,duration:1.2,stagger:.18,ease:'power2.out'},69.4);
tl.to('#prob-2',{scaleY:.6,duration:.7,yoyo:true,repeat:3},72.4);tl.to('#prob-4',{scaleY:1.12,duration:.7,yoyo:true,repeat:3},72.4);
tl.fromTo('#ap-07',{x:0},{x:820,duration:8,ease:'none'},68);
// Generated pulse patterns and binned replay visibly converge on one receiver.
tl.fromTo('#s08 .timeline-wave i',{scaleY:.12},{scaleY:1,duration:.7,stagger:.13,ease:'power2.out'},78.5);
tl.fromTo('#s08 .data-source:first-child',{x:-80,opacity:0},{x:0,opacity:1,duration:.9,ease:'power3.out'},77.6);
tl.fromTo('#s08 .data-source:last-child',{x:80,opacity:0},{x:0,opacity:1,duration:.9,ease:'power3.out'},77.9);
tl.fromTo('#s08 .dotfield i',{opacity:0,scale:.1},{opacity:1,scale:1,duration:.28,stagger:.085,ease:'power2.out'},79.5);
tl.fromTo('#arrow-08',{x:-25,opacity:.3},{x:25,opacity:1,duration:1.1,yoyo:true,repeat:5,ease:'sine.inOut'},80.0);
tl.fromTo('#gate-08',{scale:.8,opacity:.4},{scale:1,opacity:1,duration:.7,ease:'power3.out'},83.0);
tl.fromTo('#ap-08',{x:0},{x:850,duration:8.5,ease:'none'},78.5);
// Measured bars; both use a clearly disclosed zoomed 0–0.15 scale.
tl.fromTo('#bar-base',{scaleX:0},{scaleX:1,duration:1.5,ease:'power3.out'},91.0);
tl.fromTo('#bar-index',{scaleX:0},{scaleX:1,duration:1.7,ease:'power3.out'},92.2);
tl.fromTo('#lift-09',{opacity:0,y:50,scale:.8},{opacity:1,y:0,scale:1,duration:.75,ease:'back.out(1.5)'},94.2);
tl.fromTo('#ap-09',{x:0},{x:620,duration:9,ease:'none'},90.2);
tl.fromTo('#s10 .reach-track i',{scaleX:0},{scaleX:1,duration:1.2,stagger:.5,ease:'power2.out'},102.3);
tl.fromTo('#ap-10',{x:0},{x:570,duration:7,ease:'none'},101.5);
tl.fromTo('#s11 .final-fact',{opacity:0,x:-50},{opacity:1,x:0,duration:.7,stagger:.6,ease:'power2.out'},111.1);
tl.fromTo('#s11 .final-mark',{opacity:0,scale:.9},{opacity:1,scale:1,duration:1.2,ease:'power3.out'},113.1);
tl.fromTo('#ap-11',{x:0},{x:510,duration:7,ease:'power2.inOut'},111.1);
window.__timelines['main']=tl;
'''

html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><title>Smart Scan — Animated Solution</title><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>{CSS}</style></head><body><main id="root" data-composition-id="main" data-width="1920" data-height="1080" data-duration="119">{clips}{''.join(voices)}{score}{sfx}</main><script>{JS}</script></body></html>'''
(ROOT/'index.html').write_text(html,encoding='utf-8')
print('Built index.html with',len(voices),'voices')
